      {id:4,title:'臨海都市圏の生活文化―今治の造船・波止浜湾',publisher:'愛媛県生涯学習センター「えひめの記憶」',url:'https://www.i-manabi.jp/system/regionals/regionals/ecode:1/5/view/963'}
