    provisionalConclusion:'横山は城山と蛇行する錦川に挟まれた狭い平地で、城や役所と上級武士の屋敷以外を置く余裕が乏しかったため、対岸の錦見へ市街地を広げた。幅約200mで砂礫の川底を持つ錦川では渡船は増水時に止まり、多柱の桁橋は洗掘で流失。単一の木造アーチは距離的に困難で、石造アーチも河床条件と通水障害の懸念があった。西湖の島々に掛かる橋の絵に着想を得たとされる五連構造は中央3連が木造アーチ、両端2連が柱付き桁橋。1674年の流失後は敷石などで護床を強化。橋出米と定期架替え、1950年後の基礎近代化によって存続した。',
    openQuestions:['橋催相と橋出米の負担が身分や地域間でどう配分され、実際にどの程度徴収されたか','再建後の河床敷石・川舟の利用規制が河川の使い方と船運にどう影響したか','1950年流失の原因について、河床・山林・管理体制の寄与を一次資料でどこまで検証できるか','架替えによる木材・大工技術・財源の継承が近年どのように変わったか'],
