    "lead": "赤穂の海辺に、かつて広い塩田があった。潮を引き、太陽と風で海水を濃くする。その塩田は今、見当たらない。それなのに赤穂では、今も海水から塩がつくられている。なぜだろう。記録をたどると、1965年、西浜の塩田の大部分をセメント会社へ売り、その代わりに新しい製塩設備を導入したことがわかる。塩づくりを続けるために、塩田を手放す。赤穂には、そんな一見矛盾した選択があった。",
