    provisionalConclusion:'日生の吉井川・千種川、広島湾の太田川という異なる水系から養分を受け、島や岬の地形によって海水の滞留と交換が変わる。牡蠣の成長はその水中の植物プランクトンに支えられる。2025年のへい死は水温・塩分・酸素等の変動が大きな影響を持つことを示した。アマモ再生は地域の別の生態系保全であり、牡蠣の直接的な餌供給と混同しない。',
