    "provisionalConclusion": "広島湾の牡蠣は、島影の静穏と太田川などが運ぶ栄養を背景に養殖され、その多くはむき身で出荷されるため大量の殻が残る。殻は海中堆積・陸揚げ・粉砕の工程を経て、肥料や飼料、壁材へ使われてきた。丸栄の壁材「貝適空間Hiroshima折り鶴」は広島市が提供する平和記念公園の折り鶴を紙片にして牡蠣殻の粉末と混ぜ、2023年に開いたシミント広島のマザーハウス店舗にも採用された。MAZDA ICONIC SPではコンセプトカーの意匠部品にも採用された。これは産業規模の循環が完成したと示すものではなく、海の自然条件と広島の文化・産業が一つの素材の中で出会うという物語である。",
