          {
            "text": "日本で産業としてのオリーブ栽培が試みられたのは1908年。政府はオリーブオイルを使って魚介類を保存し、海外へ輸出することも考えていた。香川・三重・鹿児島で試験栽培が始まり、小豆島の西村地区に植えられた苗木が順調に育ち、数年後には油を搾れるようになった。小豆島のオリーブの物語は、最初から海の仕事と無縁ではなかった。",
            "refs": [
              3,
              4
            ]
          },
          {
            "text": "ただ、苗木が根づいたことと、産地が育つことは別だ。輸入品に押された時代もあれば、害虫のオリーブアナアキゾウムシに苦しめられた時代もある。今のオリーブ畑は「地中海に似ているからできた」のではなく、長く栽培をつないできた人々の選択の上に広がっている。",
            "refs": [
              3
            ]
          }
