            "text": "小豆島を旅するなら、景色の続きを食卓で確かめられる。西村の「オリーブ牛焼肉 妃牛」は、地元の小豆島オリーブ牛を焼肉や炙りたたきで味わえる店。蒲生の井上誠耕園「レストラン忠左衛門」では、オリーブ畑と海を望む場所で、オリーブオイルを使う料理にオリーブ牛のタリアータやミートソースが並ぶ。",
