            "text": "土庄町の「オリビアン小豆島 夕陽ヶ丘ホテル」内にあるブッフェレストラン「シエル」でも、公式メニューにはオリーブ牛のステーキが載る。島の料理店を巡ると、オリーブは畑で育つ木であると同時に、料理の名前であり、旅の思い出にもなっていることに気づく。なお、料理内容や営業日は変わるため、訪問前には各店の最新案内を確かめたい。",
